async function mutate(fn,msg='تم الحفظ بنجاح'){if(window.setBusy)window.setBusy(true,'جاري حفظ العملية');try{let r=await Store.run(fn);S=r.state;render();toast(msg);return r.result}finally{if(window.setBusy)window.setBusy(false)}}
function modal(title,html,save,submit='حفظ'){modalSave=save;$('#modalTitle').textContent=title;$('#modalBody').innerHTML=html;$('#modalError').textContent='';$('#submitModal').textContent=submit;$('#submitModal').style.display=save?'':'none';$('#cancelModal').textContent=save?'إلغاء':'إغلاق';if(!$('#modal').open)$('#modal').showModal();}
function closeModal(){$('#modal').close();if(window.cameraStream){window.cameraStream.getTracks().forEach(t=>t.stop());window.cameraStream=null}}
