$('#modalForm').onsubmit=async e=>{e.preventDefault();let btn=$('#submitModal');btn.disabled=true;$('#modalError').textContent='';try{const result=modalSave?await modalSave(new FormData(e.target)):undefined;if(result!==false)closeModal()}catch(err){$('#modalError').textContent=err.message;console.error(err)}finally{btn.disabled=false}};
