function table(headers,rows,all=false){exportHeaders=headers;exportData=rows.map(r=>r.map(c=>typeof c==='object'?c.text:c));if(!rows.length)return '<div class="empty"><div class="empty-icon">◇</div>لا توجد بيانات بعد<small style="display:block">أضف أول عملية لتبدأ متابعة أعمالك.</small></div>';let pages=Math.ceil(rows.length/25);page=Math.min(Math.max(1,page),pages);return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${(all?rows:rows.slice((page-1)*25,page*25)).map(row=>'<tr>'+row.map(c=>`<td>${typeof c==='object'?c.html:esc(c)}</td>`).join('')+'</tr>').join('')}</tbody></table></div><div class="pager" ${all?'style="display:none"':''}><span>${rows.length} نتيجة • الإجماليات تشمل جميع النتائج</span><div><button data-page="${page-1}" ${page<=1?'disabled':''}>السابق</button><span>${page} / ${pages}</span><button data-page="${page+1}" ${page>=pages?'disabled':''}>التالي</button></div></div>`}
