function match(x){return !query||JSON.stringify(x).toLowerCase().includes(query.toLowerCase())}
function docFilter(d){return (!filter.from||d.date>=filter.from)&&(!filter.to||d.date<=filter.to)&&(!filter.branch||d.branch===filter.branch)&&(!filter.party||d.party===filter.party)&&(!filter.rep||d.rep===filter.rep)&&(!filter.warehouse||d.warehouse===filter.warehouse)&&(!filter.kind||d.kind===filter.kind)}
function heading(title,sub,actions=''){return `<div class="page-head"><div><h1>${title}</h1><p>${sub}</p></div><div class="actions">${actions}</div></div>`}
function render(){if(!S)return;$('#companyLabel').innerHTML=`<b>${esc(S.settings.company)}</b><small>الإدارة المحلية · ${esc(S.settings.currency)}</small>`;$('#nav').innerHTML=nav.map(([k,l,g])=>(g?`<div class="group">${g}</div>`:'')+`<a href="#${k}" class="${route===k?'active':''}">${icon(k)}${l}</a>`).join('');if($('#bottomNav').dataset.routeRendered!==route)$('#bottomNav').innerHTML=nav.filter(x=>['dashboard','pos','invoices','vouchers','reports'].includes(x[0])).map(([k,l])=>`<a href="#${k}" class="${route===k?'active':''}">${icon(k)}${k==='invoices'?'الفواتير':k==='vouchers'?'السندات':l}</a>`).join('');$('#crumb').textContent=nav.find(x=>x[0]===route)?.[1]||'الرئيسية';let fn={dashboard,products:productsPage,parties:partiesPage,invoices:invoicesPage,vouchers:vouchersPage,inventory:inventoryPage,reps:repsPage,accounts:accountsPage,reports:reportsPage,employees:employeesPage,manufacture:manufacturePage,settings:settingsPage,pos:posPage,trading:()=>'',stockCurrent:()=>'',popularProducts:()=>'',cashierRecords:()=>''}[route]||dashboard;$('#content').innerHTML=fn();}
function dashboard(){let ds=S.docs.filter(docFilter),tr=E.trial(S,filter),b=id=>tr.find(x=>x.id===id)?.balance||0,rev=-E.sum(tr.filter(x=>x.type==='revenue'),x=>x.balance),expense=E.sum(tr.filter(x=>x.type==='expense'),x=>x.balance),cash=E.sum(tr.filter(x=>x.parent==='110'),x=>x.balance);let sales=ds.filter(d=>d.kind==='sale'&&!d.reversed),purchases=ds.filter(d=>d.kind==='purchase'&&!d.reversed);let months=Array.from({length:6},(_,i)=>{let date=new Date();date.setMonth(date.getMonth()-5+i);return date.toISOString().slice(0,7)}),values=months.map(m=>E.sum(sales.filter(d=>d.date.startsWith(m)),x=>x.totalBase)),max=Math.max(...values,1);let lows=S.products.filter(p=>p.type!=='service'&&!p.archived&&E.sum(S.warehouses,w=>E.stock(S,p.id,w.id).qty)<=p.min);return heading('نظرة شاملة على أعمالك','كل أرقامك في مكان واحد، محسوبة من العمليات المرحلة.',`<button data-action="filter">تصفية الفترة</button>`)+`<section class="welcome"><div><span class="badge">مساحة عملك المالية</span><h2>أهلاً بك في الوثيق</h2><p>${S.docs.length?'تابع أعمالك، راقب مخزونك، واتخذ قراراتك بثقة.':'ابدأ بإضافة أصنافك، ثم سجّل أول عملية شراء أو رصيد افتتاحي.'}</p><button class="primary" data-new="sale">إنشاء فاتورة بيع ←</button> <button data-action="${S.docs.length?'backup':'demo'}">${S.docs.length?'نسخة احتياطية':'تحميل بيانات توضيحية'}</button></div><div class="orb">ر</div></section><div class="stats">${stat('صافي المبيعات',money(-b('410')),S.settings.currency+' • بعد المرتجعات','arrow')}${stat('صافي نتيجة الفترة',money(rev-expense),'الإيرادات − جميع المصروفات','reports')}${stat('أرصدة النقد والبنوك',money(cash),'صافي الحركة ضمن الفترة','cash')}${stat('قيمة المخزون الحالية',money(E.sum(Object.values(S.stock),x=>x.value)),'بالتكلفة • جميع المستودعات','products')}</div><div class="grid-two"><section class="panel chart-panel"><div class="panel-title"><h3>حركة المبيعات</h3><small>آخر 6 أشهر · قبل المرتجعات</small></div><div class="bars">${months.map((m,i)=>`<div class="bar-col"><div class="bar" title="${m}: ${money(values[i])}" style="height:${Math.max(values[i]/max*100,1)}%"></div><small>${m}</small></div>`).join('')}</div></section><section class="panel"><div class="panel-title"><h3>الوصول السريع</h3><small>أنجز عمليتك مباشرة</small></div><div class="quick-grid">${[['sale','بيع','pos'],['purchase','شراء','products'],['receipt','قبض','cash'],['payment','صرف','vouchers'],['transfer','تحويل','reps'],['count','جرد','inventory']].map(([k,l,i])=>`<button data-new="${k}">${icon(i)}${l}</button>`).join('')}</div></section></div><div class="stats">${stat('الذمم المدينة',money(b('120')),'حركة حساب العملاء','parties')}${stat('الذمم الدائنة',money(-b('210')),'حركة حساب الموردين','parties')}${stat('المشتريات',money(E.sum(purchases,d=>d.totalBase)),'قيمة الفواتير قبل المرتجعات','invoices')}${stat('أصناف منخفضة المخزون',lows.length,'تحت أو عند حد الطلب','inventory')}</div><div class="grid-two"><section class="panel"><div class="panel-title"><h3>آخر العمليات</h3><a href="#invoices" class="muted">عرض الفواتير ←</a></div>${table(['الرقم','العملية','التاريخ','القيمة',''],[...ds].reverse().slice(0,8).map(d=>[d.number,E.labels[d.kind],d.date,money(d.totalBase||d.cost||0),viewCell(d.id)]))}</section><section class="panel"><div class="panel-title"><h3>متابعة الأعمال</h3><small>الأرصدة الحالية</small></div><div class="metric-line"><span>عدد العملاء والموردين</span><b>${S.parties.length}</b></div><div class="metric-line"><span>الفواتير غير المسددة</span><b>${S.docs.filter(d=>['sale','purchase'].includes(d.kind)&&!d.reversed&&E.outstanding(S,d)>0).length}</b></div><div class="metric-line"><span>الأصناف النشطة</span><b>${S.products.filter(p=>!p.archived).length}</b></div>${lows.slice(0,3).map(p=>`<div class="list-item"><div>${esc(p.name)}<small>يحتاج إلى إعادة طلب</small></div><b class="red">${qty(E.sum(S.warehouses,w=>E.stock(S,p.id,w.id).qty))}</b></div>`).join('')}</section></div>`}
function productsPage(){let ps=S.products.filter(match);return heading('الأصناف والوحدات','وحدات متعددة، أسعار مستقلة، ومخزون بالوحدة الأساسية.',`<button data-add="products" class="primary">＋ إضافة صنف</button>`)+`<div class="stats">${stat('الأصناف',S.products.length,'يشمل المؤرشف','products')}${stat('التصنيفات',new Set(S.products.map(x=>x.category).filter(Boolean)).size,'تصنيفات الأصناف','products')}${stat('قيمة التكلفة',money(E.sum(Object.values(S.stock),x=>x.value)),'جميع المستودعات','cash')}${stat('قيمة البيع',money(E.sum(S.products,p=>E.md(E.sum(S.warehouses,w=>E.stock(S,p.id,w.id).qty),p.units[0].price,1000))))}</div><section class="panel">${toolbar()}${table(['الرقم','الصنف','التصنيف','الوحدات','المخزون الأساسي','سعر البيع','الحالة',''],ps.map(p=>[p.code,p.name,p.category||'—',p.units.map(u=>u.name).join(' / '),qty(E.sum(S.warehouses,w=>E.stock(S,p.id,w.id).qty)),money(p.units[0].price),badge(p.archived?'مؤرشف':'نشط',p.archived),editCell('products',p.id)]))}</section>`}
function partiesPage(){return heading('العملاء والموردون','الأرصدة مرتبطة مباشرة بالأستاذ العام.',`<button data-add="parties" class="primary">＋ إضافة طرف</button>`)+`<section class="panel">${toolbar()}${table(['الاسم','النوع','الهاتف','رصيد لنا','رصيد علينا',''],S.parties.filter(match).map(p=>[p.name,['supplier','both'].includes(p.type)?'مورد':'عميل',p.phone,money(E.balance(S,'120',p.id)),money(-E.balance(S,'210',p.id)),htmlCell(`<button data-statement="${p.id}">كشف حساب</button> <button data-edit="parties:${p.id}">تعديل</button>`)]))}</section>`}
function invoicesPage(){let ds=S.docs.filter(d=>['sale','purchase','saleReturn','purchaseReturn'].includes(d.kind)&&(!d.reversed||window.showCancelledInvoices)&&docFilter(d)&&match({...d,partyName:name('parties',d.party)})).reverse();return heading('الفواتير','فواتير مرحلة ومرتجعات مرتبطة بالأصل.',`<button data-new="purchase">＋ شراء</button><button data-new="sale" class="primary">＋ بيع</button>`)+`<div class="tabs"><button data-action="drafts">المسودات والمعلّقة (${S.drafts.length})</button><button data-action="quote">عرض سعر / طلب بيع</button></div><section class="panel">${toolbar()}${table(['الرقم','التاريخ','النوع','الطرف','المستودع','العملة','الإجمالي','المستحق الأساسي','الحالة',''],ds.map(d=>[d.number,d.date,E.labels[d.kind],name('parties',d.party),name('warehouses',d.warehouse),d.currency,money(d.total),money(E.outstanding(S,d)),badge(d.deleted?'ملغاة':d.replacedBy?'معدلة':d.reversed?'معكوسة':'مرحلة',!!d.reversed),htmlCell(`<button data-view="${d.id}">عرض</button> ${!d.reversed?`<button data-editinvoice="${d.id}">تعديل</button><button data-deleteinvoice="${d.id}" class="danger">حذف</button>`:''}`)]))}</section>`}
function vouchersPage(){let ds=S.docs.filter(d=>['receipt','payment','cashTransfer'].includes(d.kind)&&docFilter(d)&&match(d)).reverse();return heading('القبض والصرف','التحصيل يسدد الذمم دون إعادة تسجيل إيراد.',`<button data-new="payment">＋ صرف</button><button data-new="receipt" class="primary">＋ قبض</button>`)+`<div class="stats">${S.accounts.filter(a=>a.parent==='110').map(a=>stat(a.name,money(E.balance(S,a.id)),S.settings.currency)).join('')}</div><section class="panel">${toolbar('<button data-new="cashTransfer">تحويل بين الحسابات</button><button data-action="shift">ورديات الصندوق</button>')}${table(['الرقم','التاريخ','النوع','الطرف / البيان','المبلغ','العملة','الحالة',''],ds.map(d=>[d.number,d.date,E.labels[d.kind],name('parties',d.party)+' '+(d.note||''),money(d.amount),d.currency,badge(d.reversed?'معكوس':'مرحل',!!d.reversed),viewCell(d.id)]))}</section>`}
function inventoryPage(){let rows=[];for(const w of S.warehouses){if(filter.warehouse&&w.id!==filter.warehouse)continue;for(const p of S.products.filter(p=>p.type!=='service'&&match(p))){let b=E.stock(S,p.id,w.id);if(!b.qty&&!b.value)continue;rows.push([p.name,w.name,qty(b.qty),p.units[0].name,money(b.qty?E.md(b.value,1000,b.qty):0),money(b.value),p.units.map(u=>`${u.name}: ${qty(E.md(b.qty,1000,u.factor))}`).join(' / ')])}}return heading('المخازن والجرد','تحويلات بسعر التكلفة وجرد فعلي وتسوية محاسبية.',`<button data-add="warehouses">＋ مخزن</button><button data-new="transfer" class="primary">＋ تحويل</button>`)+`<div class="tabs">${[['opening','أرصدة افتتاحية'],['count','جرد وتسوية'],['damage','تسجيل تالف']].map(([k,l])=>`<button data-new="${k}">${l}</button>`).join('')}<button data-action="stockHistory">سجل الحركات</button></div><section class="panel">${toolbar()}${table(['الصنف','المستودع','الكمية','الوحدة','متوسط التكلفة','قيمة المخزون','مكافئ الوحدات'],rows)}</section>`}
function repsPage(){return heading('المناديب والتوزيع','عهدة البضاعة مستقلة عن المبيعات والتحصيلات.',`<button data-add="reps" class="primary">＋ إضافة مندوب</button>`)+`<div class="tabs"><button data-new="transfer">تحميل / إرجاع بضاعة</button><button data-new="commission">احتساب عمولة</button><button data-new="cashTransfer">توريد نقدية</button><button data-new="damage">تالف</button></div><section class="panel">${toolbar()}${table(['المندوب','الهاتف','مستودع السيارة','سياسة العمولة','مبيعات صافية','عهدة بالتكلفة',''],S.reps.filter(match).map(r=>[r.name,r.phone,name('warehouses',r.warehouse),({sales:'المبيعات',profit:'الربح',collections:'التحصيل'}[r.commissionBasis])+' '+fmt(r.commissionRate)+'%',money(E.sum(S.docs.filter(d=>d.rep===r.id&&!d.reversed&&['sale','saleReturn'].includes(d.kind)),d=>(d.kind==='sale'?1:-1)*d.totalBase)),money(E.sum(S.products,p=>E.stock(S,p.id,r.warehouse).value)),htmlCell(`<button data-rep="${r.id}">واجهة المندوب</button> <button data-edit="reps:${r.id}">تعديل</button>`)]))}</section>`}
function accountsPage(){let rows=E.trial(S,filter);return heading('المحاسبة العامة','قيود متوازنة وأرصدة مشتقة من المستندات.',`<button data-add="accounts">＋ حساب</button><button data-new="journal" class="primary">＋ قيد يومية</button>`)+`<div class="tabs"><button data-action="journals">دفتر اليومية</button><button data-action="openingCash">قيد افتتاحي</button><button data-action="closePeriod">إقفال فترة</button><button data-add="costCenters">＋ مركز تكلفة</button></div><section class="panel">${toolbar()}${table(['الحساب','الاسم','النوع','مدين','دائن','الرصيد',''],rows.filter(match).map(a=>[a.id,a.name,{asset:'أصل',liability:'التزام',equity:'ملكية',revenue:'إيراد',expense:'مصروف'}[a.type],money(a.debit),money(a.credit),money(a.balance),htmlCell(`<button data-ledger="${a.id}">الأستاذ</button>`)]))}<div class="summary"><div><span>مجموع المدين</span><strong>${money(E.sum(rows,r=>r.debit))}</strong></div><div><span>مجموع الدائن</span><strong>${money(E.sum(rows,r=>r.credit))}</strong></div><div><span>فرق الميزان</span><strong>${money(E.sum(rows,r=>r.balance))}</strong></div></div></section>`}
const reportList=[['trial','ميزان المراجعة'],['income','قائمة الدخل'],['balance','الميزانية العمومية'],['sales','تقرير المبيعات والأرباح'],['purchases','تقرير المشتريات'],['stock','قيمة المخزون'],['aging','أعمار الديون'],['cash','حركة النقد'],['tax','حركة الضرائب'],['commission','العمولات المستحقة'],['cost','مراكز التكلفة'],['branch','مقارنة الفروع'],['rep','مقارنة المناديب']];
function reportsPage(){let rows=[],headers=[],tr=E.trial(S,filter),ds=S.docs.filter(docFilter),total='';switch(report){case'trial':headers=['الرمز','الحساب','مدين','دائن','رصيد مدين','رصيد دائن'];rows=tr.map(a=>[a.id,a.name,money(a.debit),money(a.credit),money(Math.max(0,a.balance)),money(Math.max(0,-a.balance))]);total=`المدين ${money(E.sum(tr,a=>a.debit))} • الدائن ${money(E.sum(tr,a=>a.credit))}`;break;case'income':headers=['الحساب','القيمة'];rows=tr.filter(a=>['revenue','expense'].includes(a.type)).map(a=>[a.name,money(a.type==='revenue'?-a.balance:a.balance)]);total='صافي النتيجة: '+money(-E.sum(tr.filter(a=>['revenue','expense'].includes(a.type)),a=>a.balance));break;case'balance':{let bs=E.trial(S,{to:filter.to,branch:filter.branch});headers=['الحساب','التصنيف','الرصيد'];rows=bs.filter(a=>['asset','liability','equity'].includes(a.type)).map(a=>[a.name,a.type,money(a.type==='asset'?a.balance:-a.balance)]);let profit=-E.sum(bs.filter(a=>['revenue','expense'].includes(a.type)),a=>a.balance);rows.push(['نتيجة الفترة الحالية','equity',money(profit)]);total='الأصول: '+money(E.sum(bs.filter(a=>a.type==='asset'),a=>a.balance))+' • الالتزامات والملكية مع النتيجة: '+money(-E.sum(bs.filter(a=>['liability','equity'].includes(a.type)),a=>a.balance)+profit);break}case'sales':case'purchases':headers=['الرقم','التاريخ','الطرف','النوع','الإجمالي الأساسي','التكلفة','الربح'];rows=ds.filter(d=>!d.reversed&&(report==='sales'?['sale','saleReturn']:['purchase','purchaseReturn']).includes(d.kind)).map(d=>[d.number,d.date,name('parties',d.party),E.labels[d.kind],money(d.totalBase),money(d.cost),money(report==='sales'?d.totalBase-(d.taxBase||0)-d.cost:0)]);total='المرتجعات تعرض موجبة في الصف؛ ملخص الربح الصافي من قائمة الدخل.';break;case'stock':headers=['الصنف','المستودع','كمية أساسية','قيمة التكلفة'];for(const p of S.products)for(const w of S.warehouses){let b=E.stock(S,p.id,w.id);if(b.qty&&(!filter.warehouse||w.id===filter.warehouse))rows.push([p.name,w.name,qty(b.qty),money(b.value)])}total='رصيد حالي • لا يتأثر بفترة التاريخ';break;case'aging':headers=['الفاتورة','الطرف','النوع','الاستحقاق','0–30 يوم','31–60 يوم','61–90 يوم','أكثر من 90'];for(const d of ds.filter(d=>!d.reversed&&['sale','purchase'].includes(d.kind))){let rem=E.outstanding(S,d);if(!rem)continue;let date=d.due||d.date,days=Math.max(0,Math.floor((new Date(today())-new Date(date))/86400000)),bucket=days<=30?0:days<=60?1:days<=90?2:3;rows.push([d.number,name('parties',d.party),E.labels[d.kind],date,...[0,1,2,3].map(i=>money(i===bucket?rem:0))])}total='الأرصدة الحالية، العمر محسوب من الاستحقاق حتى اليوم.';break;case'cash':case'tax':headers=['التاريخ','المرجع','الحساب','مدين','دائن','البيان'];for(const d of ds)for(const e of d.entries)if(report==='cash'?S.accounts.some(a=>a.id===e.account&&a.parent==='110'):['140','220'].includes(e.account))rows.push([d.date,d.number,name('accounts',e.account),money(e.debit),money(e.credit),d.note||E.labels[d.kind]]);break;case'commission':headers=['المندوب','من','إلى','الأساس','المستحق'];rows=ds.filter(d=>d.kind==='commission'&&!d.reversed).map(d=>[name('reps',d.rep),d.from,d.to,money(d.basis),money(d.totalBase)]);break;case'cost':headers=['مركز التكلفة','الإيرادات','المصروفات','الصافي'];rows=S.costCenters.map(c=>{let es=ds.flatMap(d=>d.entries).filter(e=>e.costCenter===c.id),r=-E.sum(es.filter(e=>find('accounts',e.account)?.type==='revenue'),e=>e.debit-e.credit),ex=E.sum(es.filter(e=>find('accounts',e.account)?.type==='expense'),e=>e.debit-e.credit);return[c.name,money(r),money(ex),money(r-ex)]});break;case'branch':case'rep':headers=['الاسم','صافي المبيعات قبل الضريبة','التكلفة','الربح الإجمالي'];rows=S[report==='branch'?'branches':'reps'].map(a=>{let docs=ds.filter(d=>!d.reversed&&['sale','saleReturn'].includes(d.kind)&&d[report]===a.id),net=E.sum(docs,d=>(d.kind==='sale'?1:-1)*(d.totalBase-(d.taxBase||0))),cost=E.sum(docs,d=>(d.kind==='sale'?1:-1)*d.cost);return[a.name,money(net),money(cost),money(net-cost)]});}
rows=rows.filter(match);return heading('التقارير المالية','الأرقام مستخرجة من القيود والحركات الفعلية.')+`<div class="tabs">${reportList.map(([k,l])=>`<button data-report="${k}" class="${report===k?'active':''}">${l}</button>`).join('')}</div><section class="panel"><div class="panel-title"><h2>${reportList.find(x=>x[0]===report)?.[1]}</h2><small>${esc(S.settings.currency)}</small></div>${toolbar()}${table(headers,rows)}${total?`<div class="summary">${esc(total)}</div>`:''}</section>`}
function employeesPage(){return heading('الموظفون والرواتب','استحقاق الرواتب منفصل عن سند صرفها.',`<button data-new="payroll">احتساب راتب</button><button data-add="employees" class="primary">＋ موظف</button>`)+`<div class="notice">هذه نسخة محلية لمستخدم موثوق. لا تتضمن مصادقة آمنة أو فرض صلاحيات بين مستخدمين؛ يلزم خادم لتنفيذ ذلك.</div><section class="panel">${toolbar()}${table(['الموظف','الهاتف','الوظيفة','الفرع','الراتب',''],S.employees.filter(match).map(e=>[e.name,e.phone,e.role,name('branches',e.branch),money(e.salary),editCell('employees',e.id)]))}</section>`}
function manufacturePage(){return heading('التصنيع والأصول','صرف مكونات الوصفة واستلام المنتج بالتكلفة الفعلية.',`<button data-add="recipes">＋ وصفة</button><button data-new="manufacture" class="primary">أمر تصنيع</button>`)+`<section class="panel"><h2>وصفات التصنيع</h2>${table(['الوصفة','المنتج','المكونات',''],S.recipes.filter(match).map(r=>[r.name,name('products',r.product),r.components.map(c=>name('products',c.product)+' × '+qty(c.qty)).join('، '),editCell('recipes',r.id)]))}</section><br><section class="panel"><div class="panel-title"><h2>الأصول الثابتة</h2><div><button data-add="assets">＋ أصل</button> <button data-new="depreciation">إهلاك شهري</button></div></div>${table(['الأصل','تاريخ الشراء','التكلفة','الخردة','مدة الأشهر',''],S.assets.filter(match).map(a=>[a.name,a.purchaseDate,money(a.cost),money(a.salvage),a.months,editCell('assets',a.id)]))}<p class="muted">تسجيل بطاقة الأصل لا يثبت شراءه محاسبياً؛ أثبت شراء الأصل بقيد يومية أو سند صرف إلى حساب الأصول الثابتة.</p></section>`}
function settingsPage(){return heading('الإعدادات والنسخ الاحتياطي','حفظ محلي، تصدير كامل، واستعادة مع التحقق.')+`<div class="grid-two"><section class="panel"><h2>المؤسسة</h2><div class="metric-line"><span>الاسم</span><b>${esc(S.settings.company)}</b></div><div class="metric-line"><span>العملة الأساسية</span><b>${esc(S.settings.currency)}</b></div><div class="metric-line"><span>السنة تبدأ</span><b>${esc(S.settings.yearStart)}</b></div><div class="metric-line"><span>مغلق حتى</span><b>${esc(S.settings.closedThrough||'لا توجد فترة مغلقة')}</b></div><br><button data-action="company" class="primary">تعديل بيانات المؤسسة</button></section><section class="panel"><h2>حماية البيانات</h2><p class="muted">احتفظ بنسخة خارج الجهاز بانتظام. مسح بيانات المتصفح يحذف قاعدة البيانات المحلية.</p><div class="file-actions"><button data-action="backup" class="primary">تنزيل نسخة كاملة JSON</button><button data-action="restore">استعادة نسخة</button><button data-action="validate">فحص اتساق البيانات</button></div><p class="muted">إصدار البيانات: ${S.schema} · مراجعة: ${S.revision} · مستندات: ${S.docs.length}</p></section></div><div class="grid-two"><section class="panel"><div class="panel-title"><h2>الفروع والمستودعات</h2><button data-add="branches">＋ فرع</button></div>${S.branches.map(b=>`<div class="list-item"><b>${esc(b.name)}</b><button data-edit="branches:${b.id}">تعديل</button></div>`).join('')}<hr style="border:0;border-top:1px solid var(--line)">${S.warehouses.map(w=>`<div class="list-item"><span>${esc(w.name)}<small>${esc(name('branches',w.branch))}</small></span><button data-edit="warehouses:${w.id}">تعديل</button></div>`).join('')}<button data-add="warehouses">＋ مستودع</button></section><section class="panel"><div class="panel-title"><h2>العملات وأسعار الصرف</h2><button data-add="currencies">＋ عملة</button></div>${S.currencies.map(c=>`<div class="list-item"><span>${esc(c.name)} (${esc(c.id)})</span><b>${rateNum(c.rate)}</b><button data-edit="currencies:${c.id}">تعديل</button></div>`).join('')}<p class="muted">الأسعار مدخلة يدوياً وليست أسعار سوق مباشرة.</p></section></div><section class="panel"><h2>أدوات النظام</h2><div class="file-actions" style="margin-top:15px"><button data-action="audit">سجل التدقيق</button><button data-action="import">استيراد أصناف CSV</button><button data-action="scope">الخصائص وحدود النسخة</button><button data-action="demo">تحميل بيانات توضيحية</button><button data-action="reset" class="danger">إنشاء قاعدة محلية فارغة</button></div><p class="muted">المزامنة: غير مفعّلة. سجل العمليات المحلي جاهز لربط خادم لاحقاً؛ لا تُرسل أي بيانات إلى الإنترنت.</p></section>`}
function posPage(){let ps=S.products.filter(p=>!p.archived&&match(p));return heading('نقطة البيع','ابحث بالاسم أو امسح الباركود • F2 للبحث • F8 للدفع',`<button data-action="camera">كاميرا</button><button data-action="drafts">المعلّقة</button>`)+`<div class="pos"><div class="panel"><div class="toolbar"><input id="search" placeholder="اسم الصنف أو الباركود..." value="${esc(query)}"><select id="posWarehouse">${options(S.warehouses,session.getItem('posWarehouse')||'main')}</select></div><div class="products">${ps.slice(0,80).map(p=>`<button class="product" data-cart="${p.id}"><div class="product-icon">${p.image?`<img src="${esc(p.image)}" style="width:100%;height:100%;object-fit:contain">`:icon('products')}</div><b>${esc(p.name)}</b><small>${esc(p.units[0].name)}</small><strong>${money(p.units[0].price)} <small>${esc(S.settings.currency)}</small></strong></button>`).join('')||'<div class="empty">لا توجد أصناف</div>'}</div>${ps.length>80?'<p class="muted">استخدم البحث للوصول إلى بقية الأصناف.</p>':''}</div><section class="panel cart"><div class="panel-title"><h2>الفاتورة الحالية</h2><small>${cart.length} بند</small></div><div class="cart-list">${cart.map((l,i)=>{let p=find('products',l.product);return `<div class="cart-item"><b>${esc(p.name)}</b><div><select data-cart-unit="${i}">${p.units.map((u,j)=>`<option value="${j}" ${j===l.unit?'selected':''}>${esc(u.name)}</option>`).join('')}</select><input aria-label="الكمية" data-cart-qty="${i}" value="${qnum(l.qty)}" inputmode="decimal"><input aria-label="السعر" data-cart-price="${i}" value="${num(l.price)}" inputmode="decimal"><button data-cart-delete="${i}">×</button></div></div>`}).join('')||'<div class="empty">أضف أصنافاً للفاتورة</div>'}</div><div class="cart-total"><span>قبل الضريبة</span><span>${money(E.sum(cart,l=>E.md(l.qty,l.price,1000)))}</span></div><button data-action="checkout" class="primary">الدفع والترحيل ←</button><div class="file-actions" style="margin-top:10px"><button data-action="suspend">تعليق</button><button data-action="clearCart">تفريغ</button></div></section></div>`}
function editEntity(t,id){let e=E.clone(find(t,id)||{}),body='',extraRead=()=>({});const basic=()=>field('الاسم','name',e.name||'','text','required');if(t==='products'){let units=e.units||[{name:'حبة',factor:1000,price:0,barcode:'',decimal:false}];body=`<div class="form-grid">${basic()}${field('رقم الصنف','code',e.code||'P'+String(S.products.length+1).padStart(4,'0'))}${field('الاسم الإنجليزي','english',e.english||'')}${field('التصنيف','category',e.category||'')}${select('النوع','type',[{id:'stock',name:'مخزني'},{id:'service',name:'خدمي'},{id:'raw',name:'مادة أولية'},{id:'finished',name:'منتج مصنع'},{id:'composite',name:'مركب'}],e.type||'stock')}${field('الضريبة %','tax',num(e.tax||0),'number','min="0" max="100" step="0.01"')}${field('حد الطلب بالوحدة الأساسية','min',qnum(e.min||0),'number','min="0" step="0.001"')}${field('العلامة التجارية','brand',e.brand||'')}${select('المورد الافتراضي','supplier',S.parties.filter(p=>['supplier','both'].includes(p.type)),e.supplier,true)}${field('صورة الصنف — ملف محلي','image','','file','accept="image/*"')}<label>الحالة<select name="archived"><option value="">نشط</option><option value="1" ${e.archived?'selected':''}>مؤرشف</option></select></label></div><div class="section-label">الوحدات والتحويلات</div><div class="notice">المعامل هو عدد الوحدات الأساسية: حبة = 1، باكيت = 24، كرتونة = 288. يمكن إضافة عدد غير محدود من الوحدات. لا يمكن تغيير المعاملات بعد حركة مخزنية.</div><div id="unitsRows"></div><button type="button" id="addUnit">＋ وحدة</button>`;
modal(e.id?'تعديل صنف':'صنف جديد',body,async f=>{let us=$$('#unitsRows .line-row').map(row=>({name:row.querySelector('[data-u=name]').value,factor:E.dec(row.querySelector('[data-u=factor]').value,3),price:E.dec(row.querySelector('[data-u=price]').value),barcode:row.querySelector('[data-u=barcode]').value,buyPrice:E.dec(row.querySelector('[data-u=buyPrice]').value),wholesale:E.dec(row.querySelector('[data-u=wholesale]').value),decimal:row.querySelector('[data-u=decimal]').checked}));let image=e.image||'';let file=f.get('image');if(file?.size){if(file.size>800000)throw Error('حجم الصورة يجب أن يكون أقل من 800 كيلوبايت');image=await readFile(file,'data')}const r20Variants=window.r20ReadNewVariants?window.r20ReadNewVariants():[];await mutate(s=>{for(const id of f.getAll('removedVariant')){const child=s.products.find(v=>v.id===id&&v.variantOf===e.id);if(child)child.archived=true}const saved=E.put(s,t,{...e,id:e.id||E.uid(),name:f.get('name'),code:f.get('code'),english:f.get('english'),category:f.get('category'),type:f.get('type'),tax:E.dec(f.get('tax')),min:E.dec(f.get('min'),3),brand:f.get('brand'),supplier:f.get('supplier'),image,taxRateId:f.get('taxRateId')||'',productGroup:f.get('productGroup')||'',brandId:f.get('brandId')||'',warranty:f.get('warranty')||'',variantOf:f.get('variantOf')||'',variantLabel:f.get('variantLabel')||'',archived:!!f.get('archived'),units:us});if(r20Variants.length){if(saved.variantOf)throw Error('لا يمكن إضافة متغيرات لمتغير فرعي');for(const v of r20Variants){const oldVariant=v.id?s.products.find(p=>p.id===v.id&&p.variantOf===saved.id):null;
 if(v.id&&!oldVariant)throw Error('المتغير الذي تحاول تعديله غير موجود');
 if(s.products.some(p=>p.id!==oldVariant?.id&&p.code&&p.code===v.code))throw Error('رمز الصنف مكرر: '+v.code);
 E.put(s,'products',{...(oldVariant||saved),id:oldVariant?.id||E.uid(),name:saved.name+' — '+v.label,code:v.code,variantOf:saved.id,variantLabel:v.label,archived:oldVariant?.archived||false,units:v.units||saved.units.map((u,i)=>({...u,barcode:i===0?v.barcode:'',price:i===0?v.price:u.price,buyPrice:i===0?v.buyPrice:u.buyPrice}))})}}})});let draw=()=>{$('#unitsRows').innerHTML=units.map((u,i)=>`<div class="line-row"><label>اسم الوحدة<input data-u="name" value="${esc(u.name)}" required></label><label>المعامل<input data-u="factor" value="${qnum(u.factor)}" required></label><label>سعر البيع<input data-u="price" value="${num(u.price)}" required></label><label>سعر الشراء<input data-u="buyPrice" value="${num(u.buyPrice||0)}" required></label><label>سعر الجملة<input data-u="wholesale" value="${num(u.wholesale||0)}" required></label><label>الباركود<input data-u="barcode" value="${esc(u.barcode||'')}"></label><label>كسور<input data-u="decimal" type="checkbox" ${u.decimal?'checked':''}></label><button type="button" data-remove-unit="${i}" ${i===0?'disabled':''}>×</button></div>`).join('')};let collect=()=>units=$$('#unitsRows .line-row').map(r=>({name:r.querySelector('[data-u=name]').value,factor:E.dec(r.querySelector('[data-u=factor]').value,3),price:E.dec(r.querySelector('[data-u=price]').value),barcode:r.querySelector('[data-u=barcode]').value,buyPrice:E.dec(r.querySelector('[data-u=buyPrice]').value),wholesale:E.dec(r.querySelector('[data-u=wholesale]').value),decimal:r.querySelector('[data-u=decimal]').checked}));draw();$('#addUnit').onclick=()=>{try{collect();units.push({name:'',factor:1000,price:0});draw()}catch(err){error(err)}};$('#unitsRows').onclick=ev=>{let b=ev.target.closest('[data-remove-unit]');if(b){collect();units.splice(+b.dataset.removeUnit,1);draw()}};return}
if(t==='parties'){body=basic()+select('نوع الطرف','type',[{id:'customer',name:'عميل'},{id:'supplier',name:'مورد'}],e.type)+field('الهاتف','phone',e.phone||'')+field('العنوان','address',e.address||'')+field('حد ائتماني بالعملة الأساسية — صفر بلا حد','creditLimit',num(e.creditLimit||0),'number','min="0" step="0.01"')+field('مدة السداد بالأيام','terms',e.terms||0,'number','min="0"')+field('المجموعة','group',e.group||'');extraRead=f=>({creditLimit:E.dec(f.get('creditLimit')),terms:Number(f.get('terms'))})}
else if(t==='warehouses'){body=basic()+select('الفرع','branch',S.branches,e.branch)}else if(t==='branches'||t==='costCenters'){body=basic()}
else if(t==='accounts'){body=field('رمز الحساب','id',e.id||'','text',e.id?'readonly':'required')+basic()+select('نوع الحساب','type',[{id:'asset',name:'أصل'},{id:'liability',name:'التزام'},{id:'equity',name:'حقوق ملكية'},{id:'revenue',name:'إيراد'},{id:'expense',name:'مصروف'}],e.type)+select('الحساب الأب','parent',S.accounts,e.parent,true)}
else if(t==='currencies'){body=field('رمز العملة','id',e.id||'','text',e.id?'readonly':'required pattern="[A-Z]{3}"')+basic()+field('سعر الصرف إلى العملة الأساسية','rate',rateNum(e.rate),'number','min="0.000001" step="0.000001"');extraRead=f=>({rate:E.dec(f.get('rate'),6)})}
else if(t==='reps'){body=basic()+field('الهاتف','phone',e.phone||'')+select('مستودع السيارة','warehouse',S.warehouses,e.warehouse)+select('الفرع','branch',S.branches,e.branch)+field('منطقة التوزيع','area',e.area||'')+select('سياسة العمولة','commissionBasis',[{id:'sales',name:'صافي المبيعات قبل الضريبة'},{id:'profit',name:'الربح الإجمالي'},{id:'collections',name:'التحصيل النقدي'}],e.commissionBasis)+field('نسبة العمولة %','commissionRate',num(e.commissionRate||0),'number','min="0" max="100" step="0.01"')+select('حساب عهدة النقد','cash',S.accounts.filter(a=>a.parent==='110'),e.cash||'113');extraRead=f=>({commissionRate:E.dec(f.get('commissionRate'))})}
else if(t==='employees'){body=basic()+field('الهاتف','phone',e.phone||'')+field('الوظيفة','role',e.role||'محاسب')+select('الفرع','branch',S.branches,e.branch)+field('الراتب الشهري','salary',num(e.salary||0),'number','min="0" step="0.01"');extraRead=f=>({salary:E.dec(f.get('salary'))})}
else if(t==='assets'){body=basic()+field('تاريخ الشراء','purchaseDate',e.purchaseDate||today(),'date','required')+field('التكلفة','cost',num(e.cost||0),'number','min="0" step="0.01"')+field('قيمة الخردة','salvage',num(e.salvage||0),'number','min="0" step="0.01"')+field('عمر الأصل بالأشهر','months',e.months||60,'number','min="1" step="1"');extraRead=f=>{let cost=E.dec(f.get('cost')),salvage=E.dec(f.get('salvage')),months=Number(f.get('months'));if(salvage>cost||months<1||!Number.isInteger(months))throw Error('قيم الأصل غير صالحة');if(e.id&&S.docs.some(d=>d.asset===e.id))throw Error('لا تعدّل أصلًا بدأ إهلاكه');return{cost,salvage,months}}}
else if(t==='recipes'){body=basic()+select('المنتج النهائي','product',S.products.filter(p=>p.type!=='service'),e.product)+`<label class="full">المكونات لكل وحدة أساسية من المنتج<div id="components"></div><button type="button" id="addComponent">＋ مكوّن</button></label>`;extraRead=f=>{let components=$$('#components .component').map(r=>({product:r.querySelector('select').value,qty:E.dec(r.querySelector('input').value,3)}));if(!components.length||components.some(c=>c.qty<=0||c.product===f.get('product')))throw Error('تحقق من المكونات والكميات');return{components}}}
modal((e.id?'تعديل ':'إضافة ')+({parties:'طرف',warehouses:'مستودع',branches:'فرع',accounts:'حساب',currencies:'عملة',reps:'مندوب',employees:'موظف',assets:'أصل',recipes:'وصفة',costCenters:'مركز تكلفة'}[t]),`<div class="form-grid">${body}</div>`,async f=>{let data={...e,...Object.fromEntries(f),...extraRead(f)};if(!e.id&&data.id&&S[t].some(x=>x.id===data.id))throw Error('الرمز مستخدم مسبقاً');if(t==='parties'&&!e.id){const opening={amount:E.dec(f.get('openingAmount')||'0'),side:f.get('openingSide')||'receivable',date:f.get('openingDate')||today()};delete data.openingAmount;delete data.openingSide;delete data.openingDate;data.id=data.id||E.uid();await mutate(s=>r23SaveParty(s,data,opening))}else await mutate(s=>E.put(s,t,data))});if(t==='recipes'){let add=c=>{let div=document.createElement('div');div.className='component toolbar';div.innerHTML=`<select>${options(S.products.filter(p=>p.type!=='service'),c?.product)}</select><input value="${qnum(c?.qty||1000)}" aria-label="كمية المكون"><button type="button">×</button>`;div.querySelector('button').onclick=()=>div.remove();$('#components').append(div)};(e.components||[{}]).forEach(add);$('#addComponent').onclick=()=>add()}}
// Keep internal accounting dimensions in documents without asking for them on
// unrelated forms. Stock transfers alone require an explicit source warehouse.
function baseFields(d={},kind='general'){
 const wh=d.warehouse||session.getItem('posWarehouse')||S.warehouses[0]?.id||'main';
 const hidden=(k,v)=>`<input type="hidden" name="${k}" value="${esc(v||'')}">`;
 return `<div class="form-grid">${field('التاريخ','date',d.date||today(),'date','required')}${field('البيان / الملاحظات','note',d.note||'')}${kind==='transfer'?select('المستودع المصدر','warehouse',S.warehouses,wh):hidden('warehouse',wh)}${hidden('branch',d.branch||'main')}${kind==='commission'?'':hidden('rep',d.rep||'')}${hidden('costCenter',d.costCenter||'general')}</div>`;
}
function currencyFields(d={}){return select('العملة','currency',S.currencies,d.currency||S.settings.currency)+field('سعر الصرف إلى العملة الأساسية','rate',rateNum(d.rate),'number','step="0.000001" min="0.000001" required')}
function bindCurrency(){let c=$('#modalBody [name=currency]');if(c)c.onchange=()=>{$('#modalBody [name=rate]').value=rateNum(find('currencies',c.value)?.rate);updateInvoiceTotal()}}
function getBase(f){return{date:f.get('date'),branch:f.get('branch')||'main',warehouse:f.get('warehouse')||session.getItem('posWarehouse')||'main',rep:f.get('rep')||'',note:f.get('note')||'',costCenter:f.get('costCenter')||'general',currency:f.get('currency')||S.settings.currency,rate:f.has('rate')?E.dec(f.get('rate'),6):1000000}}
function paymentRow(p={}){let row=document.createElement('div');row.className='payment-row toolbar';row.innerHTML=`<select aria-label="حساب الدفع" data-p="account">${options(S.accounts.filter(a=>a.parent==='110'),p.account||'111')}</select><select aria-label="عملة الدفع" data-p="currency">${options(S.currencies,p.currency||S.settings.currency)}</select><input data-p="rate" aria-label="سعر صرف الدفعة" value="${rateNum(p.rate)}" placeholder="سعر الصرف"><input data-p="amount" aria-label="مبلغ الدفعة" value="${num(p.amount||0)}" placeholder="المبلغ"><button type="button">×</button>`;row.querySelector('button').onclick=()=>{row.remove();updateInvoiceTotal()};row.querySelector('[data-p=currency]').onchange=()=>{row.querySelector('[data-p=rate]').value=rateNum(find('currencies',row.querySelector('[data-p=currency]').value).rate);updateInvoiceTotal()};row.oninput=updateInvoiceTotal;$('#payments').append(row)}
function readPayments(){return $$('#payments .payment-row').map(r=>({account:r.querySelector('[data-p=account]').value,currency:r.querySelector('[data-p=currency]').value,rate:E.dec(r.querySelector('[data-p=rate]').value,6),amount:E.dec(r.querySelector('[data-p=amount]').value)})).filter(p=>p.amount>0)}
function readLines(){return $$('#invoiceLines .line-row').map(r=>({product:r.querySelector('[data-l=product]').value,unit:+r.querySelector('[data-l=unit]').value,qty:E.dec(r.querySelector('[data-l=qty]').value,3),price:E.dec(r.querySelector('[data-l=price]').value),discount:E.dec(r.querySelector('[data-l=discount]').value)}))}
function addInvoiceLine(l={}){let ps=S.products.filter(p=>!p.archived&&(currentKind==='sale'||p.type!=='service'));if(!ps.length){toast('أضف صنفاً أولاً');return}let p=find('products',l.product)||ps[0],u=p.units[l.unit||0];let row=document.createElement('div');row.className='line-row';row.innerHTML=`<label>الصنف<select data-l="product">${options(ps,p.id)}</select></label><label>الوحدة<select data-l="unit">${p.units.map((v,i)=>`<option value="${i}" ${i===(l.unit||0)?'selected':''}>${esc(v.name)}</option>`).join('')}</select></label><label>الكمية<input data-l="qty" inputmode="decimal" value="${qnum(l.qty??1000)}"></label><label>السعر<input data-l="price" inputmode="decimal" value="${num(l.price??(currentKind==='purchase'?(u.buyPrice||0):u.price))}"></label><label>خصم المبلغ<input data-l="discount" inputmode="decimal" value="${num(l.discount||0)}"></label><button type="button">×</button>`;row.querySelector('button').onclick=()=>{row.remove();updateInvoiceTotal()};row.querySelector('[data-l=product]').onchange=()=>{let pr=find('products',row.querySelector('[data-l=product]').value);row.querySelector('[data-l=unit]').innerHTML=pr.units.map((u,i)=>`<option value="${i}">${esc(u.name)}</option>`).join('');row.querySelector('[data-l=price]').value=num(currentKind==='purchase'?(pr.units[0].buyPrice||0):E.priceFor(S,pr.id,0,inputVal('party')));updateInvoiceTotal()};row.querySelector('[data-l=unit]').onchange=()=>{let pr=find('products',row.querySelector('[data-l=product]').value);row.querySelector('[data-l=price]').value=num(currentKind==='purchase'?(pr.units[+row.querySelector('[data-l=unit]').value].buyPrice||0):E.priceFor(S,pr.id,+row.querySelector('[data-l=unit]').value,inputVal('party')));updateInvoiceTotal()};row.oninput=updateInvoiceTotal;$('#invoiceLines').append(row);updateInvoiceTotal()}
function updateInvoiceTotal(){if(!$('#invoiceTotal'))return;try{let lines=readLines(),net=0,tax=0;for(const l of lines){let n=E.md(l.qty,l.price,1000)-l.discount;net+=n;tax+=E.md(n,find('products',l.product).tax||0,10000)}let rate=E.dec($('#modalBody [name=rate]').value,6),total=E.md(net+tax,rate,1000000),paid=E.sum(readPayments(),p=>E.md(p.amount,p.rate,1000000));$('#invoiceTotal').innerHTML=`<div><span>قبل الضريبة</span><strong>${money(net)}</strong></div><div><span>الضريبة</span><strong>${money(tax)}</strong></div><div><span>الإجمالي بالأساسية</span><strong>${money(total)}</strong></div><div><span>المدفوع</span><strong>${money(paid)}</strong></div><div><span>المتبقي</span><strong>${money(total-paid)}</strong></div>`}catch{$('#invoiceTotal').textContent='أكمل القيم الرقمية لعرض الإجمالي'}}
function invoice(kind='sale',draft={},fromCart=false){currentKind=kind;pendingId=draft.id||E.uid();let parties=S.parties.filter(p=>(p.type==='both'||p.type===(kind==='sale'?'customer':'supplier')));modal(E.labels[kind],baseFields(draft,kind)+`<div class="form-grid" style="margin-top:16px">${select(kind==='sale'?'العميل — إلزامي للآجل':'المورد — إلزامي للآجل','party',parties,draft.party,true)}${field('تاريخ الاستحقاق','due',draft.due||today(),'date')}${currencyFields(draft)}</div><div class="section-label">بنود الفاتورة</div><div id="invoiceLines"></div><button type="button" id="addLine">＋ إضافة بند</button> <button type="button" id="wholesaleBtn">تطبيق أسعار الجملة</button><div class="section-label">دفعات الفاتورة — اتركها صفرًا للبيع الآجل</div><div id="payments"></div><button type="button" id="addPayment">＋ طريقة دفع إضافية</button><div class="summary" id="invoiceTotal"></div><div class="file-actions" style="margin-top:15px"><button type="button" id="saveDraft">حفظ كمسودة دون ترحيل</button></div>`,async f=>{if(window.validatePaymentMode)window.validatePaymentMode();let input={id:pendingId,kind,...getBase(f),party:f.get('party'),due:f.get('due'),lines:readLines(),payments:readPayments(),orderId:draft.orderId,...(window.invoiceExtras?window.invoiceExtras():{})};let d=await mutate(s=>{let d=draft.editOriginal?E.amendInvoice(s,draft.editOriginal,input):E.post(s,input);s.drafts=s.drafts.filter(x=>x.id!==input.id);return d},'تم ترحيل الفاتورة والمخزون والقيود');if(fromCart){cart=[];persistCart();render()}/* المستند المحفوظ متاح من قائمة المستندات */},'حفظ وترحيل');(draft.lines?.length?draft.lines:fromCart?cart:[{}]).forEach(addInvoiceLine);(draft.payments?.length?draft.payments:[{}]).forEach(paymentRow);$('#addLine').onclick=()=>addInvoiceLine();$('#wholesaleBtn').style.display=kind==='sale'?'':'none';$('#wholesaleBtn').onclick=()=>{$$('#invoiceLines .line-row').forEach(r=>{let p=find('products',r.querySelector('[data-l=product]').value),u=p.units[+r.querySelector('[data-l=unit]').value];if(u.wholesale>0)r.querySelector('[data-l=price]').value=num(u.wholesale)});updateInvoiceTotal()};$('#addPayment').onclick=()=>{paymentRow();updateInvoiceTotal()};bindCurrency();$('#modalBody [name=rate]').oninput=updateInvoiceTotal;if(draft.editOriginal){$('#modalTitle').textContent='تعديل فاتورة #'+draft.editNumber;$('#saveDraft').style.display='none'}$('#saveDraft').onclick=async()=>{try{let f=new FormData($('#modalForm')),d={id:pendingId,kind,...getBase(f),party:f.get('party'),due:f.get('due'),lines:readLines(),payments:readPayments(),orderId:draft.orderId,...(window.invoiceExtras?window.invoiceExtras():{}),saved:today()};await mutate(s=>{s.drafts=s.drafts.filter(x=>x.id!==d.id);s.drafts.push(d)},'تم حفظ المسودة');if(fromCart){cart=[];persistCart();render()}closeModal()}catch(err){error(err)}};$('#modalBody [name=rep]').onchange=()=>{let r=find('reps',inputVal('rep'));if(r){$('#modalBody [name=warehouse]').value=r.warehouse;$('#modalBody [name=branch]').value=r.branch;let first=$('#payments [data-p=account]');if(first)first.value=r.cash||'113'}};updateInvoiceTotal()}
function voucher(kind){pendingId=E.uid();let isReceipt=kind==='receipt';modal(E.labels[kind],baseFields()+`<div class="form-grid" style="margin-top:16px">${currencyFields()}${field('المبلغ','amount','','number','min="0.01" step="0.01" required')}${select('الصندوق / البنك','cash',S.accounts.filter(a=>a.parent==='110'),'111')}${kind==='cashTransfer'?select('الحساب المستلم','targetAccount',S.accounts.filter(a=>a.parent==='110'),'112'):select('الحساب المقابل','account',S.accounts.filter(a=>!S.accounts.some(b=>b.parent===a.id)&&!['130','510','140','220'].includes(a.id)),isReceipt?'120':'210')+select('العميل / المورد','party',S.parties,'',true)}</div>${kind!=='cashTransfer'?'<div class="section-label">تسديد فواتير — بالعملة الأساسية</div><div id="allocations"></div><p class="muted">عدم التخصيص يسجل دفعة على حساب الطرف. اختر فواتير عند تسديد مستحقات محددة.</p>':''}`,async f=>{let allocations=$$('#allocations input').map(x=>({invoice:x.dataset.invoice,amount:E.dec(x.value||0)})).filter(a=>a.amount>0);let d=await mutate(s=>E.post(s,{id:pendingId,kind,...getBase(f),amount:E.dec(f.get('amount')),cash:f.get('cash'),account:f.get('account'),expenseCategory:f.get('expenseCategory')||'',reference:f.get('reference')||'',beneficiary:f.get('beneficiary')||'',expenseLocation:f.get('expenseLocation')||'',party:f.get('party'),targetAccount:f.get('targetAccount'),allocations}));/* المستند المحفوظ متاح من قائمة المستندات */},'حفظ وترحيل');bindCurrency();if(kind!=='cashTransfer'){let draw=()=>{let party=inputVal('party');$('#allocations').innerHTML=S.docs.filter(d=>!d.reversed&&d.kind===(isReceipt?'sale':'purchase')&&d.party===party&&E.outstanding(S,d)>0).map(d=>`<label style="margin-bottom:10px">فاتورة ${d.number} · مستحق ${money(E.outstanding(S,d))}<input data-invoice="${d.id}" value="0" inputmode="decimal"></label>`).join('')||'<small>لا توجد فواتير غير مسددة لهذا الطرف.</small>'};$('#modalBody [name=party]').onchange=draw;draw()}}
function readStockQty(r){let p=find('products',r.querySelector('select').value),u=p.units[+r.querySelector('[data-stockunit]').value],q=E.dec(r.querySelector('[data-q]').value,3);if(!u.decimal&&q%1000)throw Error('الوحدة لا تسمح بكمية كسرية');if(BigInt(q)*BigInt(u.factor)%1000n)throw Error('الكمية الأساسية أدق من 0.001');return E.md(q,u.factor,1000)}
function stockDocument(kind){pendingId=E.uid();let body=baseFields({},kind)+`<div class="form-grid" style="margin-top:16px">${kind==='transfer'?select('المستودع المستلم','toWarehouse',S.warehouses,'van'):''}</div><div class="notice">اختر وحدة الإدخال لكل صنف. يُحوّل النظام الكمية إلى الوحدة الأساسية تلقائياً. تكلفة الافتتاحي هي قيمة الكمية كلها.</div><div id="stockLines"></div><button type="button" id="addStockLine">＋ صنف</button>`;modal(E.labels[kind],body,async f=>{let lines=$$('#stockLines .line-row').map(r=>({product:r.querySelector('select').value,qty:readStockQty(r),value:E.dec(r.querySelector('[data-v]')?.value||0)}));if(new Set(lines.map(l=>l.product)).size!==lines.length)throw Error('اجمع الصنف المكرر في بند واحد');await mutate(s=>E.post(s,{id:pendingId,kind,...getBase(f),toWarehouse:f.get('toWarehouse'),lines}))},'اعتماد وترحيل');const add=()=>{let r=document.createElement('div');r.className='line-row';r.innerHTML=`<label>الصنف<select>${options(S.products.filter(p=>p.type!=='service'&&!p.archived))}</select></label><label>الوحدة<select data-stockunit></select></label><label>${kind==='count'?'الكمية المعدودة':'الكمية'}<input data-q value="0"></label>${['count','opening'].includes(kind)?'<label>التكلفة الإجمالية للزيادة عند رصيد صفر<input data-v value="0"></label>':''}<button type="button">×</button>`;r.querySelector('button').onclick=()=>r.remove();$('#stockLines').append(r);let updateUnits=()=>{let p=find('products',r.querySelector('select').value);r.querySelector('[data-stockunit]').innerHTML=(p?.units||[]).map((u,i)=>`<option value="${i}">${esc(u.name)}</option>`).join('')};r.querySelector('select').onchange=updateUnits;updateUnits()};$('#addStockLine').onclick=add;add()}
function journal(){pendingId=E.uid();modal('قيد يومية يدوي',baseFields()+`<div class="notice">القيم بالعملة الأساسية. المخزون لا يُعدّل بقيد يدوي؛ استخدم مستند جرد أو افتتاحي مخزني.</div><div id="journalLines"></div><button type="button" id="addJournalLine">＋ طرف قيد</button>`,async f=>{let entries=$$('#journalLines .line-row').map(r=>({account:r.querySelector('[data-a]').value,party:r.querySelector('[data-party]').value,debit:E.dec(r.querySelector('[data-d]').value||0),credit:E.dec(r.querySelector('[data-c]').value||0)}));await mutate(s=>E.post(s,{id:pendingId,kind:'journal',...getBase(f),entries}))},'ترحيل القيد');let add=()=>{let r=document.createElement('div');r.className='line-row';r.innerHTML=`<label>الحساب<select data-a>${options(S.accounts.filter(a=>!S.accounts.some(b=>b.parent===a.id)&&a.id!=='130'))}</select></label><label>الطرف<select data-party><option value="">—</option>${options(S.parties)}</select></label><label>مدين<input data-d value="0"></label><label>دائن<input data-c value="0"></label><button type="button">×</button>`;r.querySelector('button').onclick=()=>r.remove();$('#journalLines').append(r)};$('#addJournalLine').onclick=add;add();add()}
function otherDocument(kind){pendingId=E.uid();let fields='';if(kind==='manufacture')fields=select('الوصفة','recipe',S.recipes)+field('كمية المنتج النهائي الأساسية','qty','1','number','min="0.001" step="0.001" required')+field('مصاريف تصنيع نقدية إضافية','overhead','0','number','min="0" step="0.01"')+select('الصندوق','cash',S.accounts.filter(a=>a.parent==='110'),'111');if(kind==='commission')fields=select('المندوب','rep',S.reps)+field('من','from',today().slice(0,7)+'-01','date','required')+field('إلى','to',today(),'date','required');if(kind==='payroll')fields=select('الموظف','employee',S.employees)+field('شهر الراتب','month',today().slice(0,7),'month','required');if(kind==='depreciation')fields=select('الأصل','asset',S.assets)+field('شهر الإهلاك','month',today().slice(0,7),'month','required');modal(E.labels[kind],baseFields({},kind)+`<div class="form-grid" style="margin-top:15px">${fields}</div>`,async f=>{let d={id:pendingId,kind,...Object.fromEntries(f),...getBase(f)};if(kind==='manufacture'){d.qty=E.dec(f.get('qty'),3);d.overhead=E.dec(f.get('overhead'))}await mutate(s=>E.post(s,d))},'اعتماد وترحيل')}
function newDoc(k){if(['sale','purchase'].includes(k))invoice(k);else if(['receipt','payment','cashTransfer'].includes(k))voucher(k);else if(['transfer','count','damage','opening'].includes(k))stockDocument(k);else if(k==='journal')journal();else otherDocument(k)}
function receiptHTML(d){return `<div class="receipt"><h1>${esc(S.settings.company)}</h1><div class="center">${esc(S.settings.address)}<br>${esc(S.settings.phone)}<h2>${esc(E.labels[d.kind])} ${esc(d.number)}</h2>${d.reversed?'<b>مستند معكوس</b>':''}</div><div class="meta"><span>التاريخ: ${esc(d.date)}</span><span>العملة: ${esc(d.currency)}</span><span>الطرف: ${esc(name('parties',d.party))}</span>${['transfer','count','opening','damage','sale','purchase','saleReturn','purchaseReturn','manufacture'].includes(d.kind)?`<span>المستودع: ${esc(name('warehouses',d.warehouse))}</span>`:''}</div>${d.lines.length?`<table><thead><tr><th>الصنف</th><th>الوحدة</th><th>الكمية</th><th>السعر</th><th>الإجمالي</th></tr></thead><tbody>${d.lines.map(l=>`<tr><td>${esc(l.name||name('products',l.product))}</td><td>${esc(l.unitName||'أساسية')}</td><td>${qty(l.qty||0)}</td><td>${l.price!==undefined?money(l.price):'—'}</td><td>${money(l.total??l.cost??0)}</td></tr>`).join('')}</tbody></table>`:''}<div class="totals">${d.total!==undefined?`<div><span>الإجمالي ${esc(d.currency)}</span><b>${money(d.total)}</b></div><div><span>الضريبة</span><b>${money(E.sum(d.lines,l=>l.tax||0))}</b></div>`:''}<div><span>القيمة بالعملة الأساسية</span><b>${money(d.totalBase||d.cost||0)} ${esc(S.settings.currency)}</b></div>${d.paidBase!==undefined?`<div><span>المدفوع عند الإصدار</span><b>${money(d.paidBase)}</b></div><div><span>المستحق الحالي</span><b>${money(E.outstanding(S,d))}</b></div>`:''}</div><p>${esc(d.note||'')}</p><hr><div class="center"><small>الوثيق ERP · مستند ${esc(d.number)}</small></div></div>`}
function viewDoc(id){let d=S.docs.find(x=>x.id===id);if(!d)return;modal(`${E.labels[d.kind]} #${d.number}`,`<div class="file-actions" style="margin-bottom:20px"><button type="button" data-printdoc="${id}">طباعة / PDF</button><button type="button" data-sharedoc="${id}">مشاركة النص</button>${!d.reversed&&['sale','purchase'].includes(d.kind)?`<button type="button" data-return="${id}">مرتجع جزئي / كامل</button><button type="button" data-editinvoice="${id}">تعديل الفاتورة</button><button type="button" class="danger" data-deleteinvoice="${id}">حذف الفاتورة</button>`:''}${!d.reversed&&!['reverse','close'].includes(d.kind)?`<button type="button" class="danger" data-reverse="${id}">عكس المستند</button>`:''}</div>${receiptHTML(d)}<div class="section-label">القيد المحاسبي</div><div class="table-wrap"><table><tr><th>الحساب</th><th>مدين</th><th>دائن</th></tr>${d.entries.map(e=>`<tr><td>${esc(name('accounts',e.account))}</td><td>${money(e.debit)}</td><td>${money(e.credit)}</td></tr>`).join('')}</table></div>`,null)}
function returnDoc(id){let o=S.docs.find(d=>d.id===id),kind=o.kind==='sale'?'saleReturn':'purchaseReturn',rid=E.uid();modal(E.labels[kind]+' — '+o.number,baseFields({...o,date:today()})+`<div class="form-grid" style="margin-top:15px">${select('تسوية القيمة','refundAccount',[{id:'',name:'على حساب العميل / المورد'},...S.accounts.filter(a=>a.parent==='110')],'')}</div><div class="notice">أدخل الكمية المرتجعة بالوحدة الأساسية، وبحد أقصى الكمية الأصلية ناقص المرتجع السابق.</div><div id="returnLines">${o.lines.map((l,i)=>{let used=E.sum(S.docs.filter(d=>d.original===id&&!d.reversed&&d.kind===kind).flatMap(d=>d.lines).filter(x=>x.index===i),x=>x.baseQty);return `<label style="margin-top:14px">${esc(l.name)} · المتاح ${qty(l.baseQty-used)} ${esc(find('products',l.product).units[0].name)}<input data-index="${i}" value="0" inputmode="decimal"></label>`}).join('')}</div>`,async f=>{let lines=$$('#returnLines input').map(i=>({index:+i.dataset.index,baseQty:E.dec(i.value,3)})).filter(x=>x.baseQty>0);await mutate(s=>E.post(s,{id:rid,kind,...getBase(f),original:id,refundAccount:f.get('refundAccount'),lines}))},'اعتماد المرتجع')}
function printHTML(html){$('#printArea').innerHTML=html;let st=$('#printStyle');if(!st){st=document.createElement('style');st.id='printStyle';document.head.append(st)}st.textContent=`@media print{@page{size:${S.settings.print==='A4'?'A4':S.settings.print+' auto'};margin:${S.settings.print==='A4'?'12mm':'3mm'}}`;window.print()}
function download(data,name,type='application/json'){let a=document.createElement('a'),url=URL.createObjectURL(new Blob([data],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000)}
function readFile(file,mode='text'){return new Promise((resolve,reject)=>{let r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('تعذر قراءة الملف'));mode==='data'?r.readAsDataURL(file):r.readAsText(file)})}
function chooseFile(accept,cb){let i=document.createElement('input');i.type='file';i.accept=accept;i.onchange=()=>{if(i.files[0])Promise.resolve(cb(i.files[0])).catch(error)};i.click()}
function csvExport(){let safe=v=>{let s=String(v??'');if(/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'};download('\uFEFF'+[exportHeaders,...exportData].map(r=>r.map(safe).join(',')).join('\r\n'),'Rawan-'+route+'-'+today()+'.csv','text/csv;charset=utf-8')}
function printReport(){printHTML(`<div class="receipt"><h1>${esc(S.settings.company)}</h1><h2>${esc($('#crumb').textContent)} ${route==='reports'?esc(reportList.find(x=>x[0]===report)?.[1]):''}</h2><p>${esc(today())} • ${esc(S.settings.currency)} • ${esc(filter.from||'البداية')} — ${esc(filter.to||'اليوم')}</p><table><thead><tr>${exportHeaders.map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${exportData.map(r=>`<tr>${r.map(x=>`<td>${esc(x)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`)}
function showLedger(account,party){let entries=[];let b=0;for(const d of [...S.docs].sort((a,b)=>a.date.localeCompare(b.date))){for(const e of d.entries){if(account&&e.account!==account||party&&e.party!==party)continue;b+=e.debit-e.credit;entries.push([d.date,d.number,E.labels[d.kind],name('accounts',e.account),money(e.debit),money(e.credit),money(b)])}}page=1;modal(party?'كشف حساب '+name('parties',party):'الأستاذ — '+name('accounts',account),`<div class="file-actions"><button type="button" data-action="export">CSV</button><button type="button" data-action="printReport">طباعة</button></div>${table(['التاريخ','المرجع','النوع','الحساب','مدين','دائن','الرصيد'],entries,true)}<div class="summary">الرصيد ${money(b)} ${esc(S.settings.currency)}</div>`,null)}
function filters(){modal('تصفية النتائج',`<div class="form-grid">${field('من تاريخ','from',filter.from||'','date')}${field('إلى تاريخ','to',filter.to||'','date')}${select('الفرع','branch',S.branches,filter.branch,true)}${select('المستودع','warehouse',S.warehouses,filter.warehouse,true)}${select('الطرف','party',S.parties,filter.party,true)}${select('المندوب','rep',S.reps,filter.rep,true)}${select('نوع المستند','kind',Object.entries(E.labels).map(([id,name])=>({id,name})),filter.kind,true)}</div>`,async f=>{filter=Object.fromEntries(f);page=1;render()},'تطبيق')}
function persistCart(){try{session.setItem('rawan-cart',JSON.stringify(cart))}catch{}}
function showDrafts(){modal('المسودات والعروض والطلبات',S.drafts.length?[...S.drafts].reverse().map(d=>`<div class="list-item"><div>${esc(d.draftType||E.labels[d.kind]||'معلقة')}<small>${esc(d.saved||'')} • ${d.lines.length} بنود</small></div><button type="button" data-draft="${d.id}">فتح / تحويل إلى فاتورة</button><button type="button" data-draft-delete="${d.id}">حذف</button></div>`).join(''):'<div class="empty">لا توجد مسودات</div>',null)}
function showAudit(){page=1;modal('سجل التدقيق',table(['الوقت','العملية','المرجع'],[...S.audit].reverse().map(a=>[a.time,a.action,a.name||a.ref]),true),null)}
function showJournals(){page=1;modal('دفتر اليومية',table(['الرقم','التاريخ','النوع','البيان',''],[...S.docs].reverse().map(d=>[d.number,d.date,E.labels[d.kind],d.note||'',viewCell(d.id)]),true),null)}
function showStockHistory(){let rows=[];for(const d of [...S.docs].reverse())for(const m of d.movements)rows.push([d.date,d.number,E.labels[d.kind],name('products',m.product),name('warehouses',m.warehouse),qty(m.qty),money(m.value)]);page=1;modal('سجل الحركات المخزنية',`<div class="file-actions"><button type="button" data-action="export">CSV</button><button type="button" data-action="printReport">طباعة</button></div>${table(['التاريخ','المرجع','العملية','الصنف','المستودع','الكمية','القيمة'],rows,true)}`,null)}
function showRep(id){let r=find('reps',id),sales=S.docs.filter(d=>d.rep===id&&!d.reversed&&d.kind==='sale'),cash=E.balance(S,r.cash||'113');modal('مساحة المندوب — '+r.name,`<div class="stats">${stat('المبيعات',money(E.sum(sales,d=>d.totalBase)))}${stat('عهدة النقد',money(cash),name('accounts',r.cash||'113'))}${stat('عهدة البضاعة',money(E.sum(S.products,p=>E.stock(S,p.id,r.warehouse).value)))}${stat('العمولة المحتسبة',money(E.sum(S.docs.filter(d=>d.kind==='commission'&&d.rep===id&&!d.reversed),d=>d.totalBase)))}</div><div class="quick-grid"><button type="button" id="repSale">${icon('pos')}بيع</button><button type="button" id="repReceipt">${icon('cash')}قبض</button><button type="button" data-new="count">${icon('inventory')}جرد</button></div><p class="muted">واجهة تشغيل محلية وليست حساب دخول مستقلًا. عيّن صندوقاً مستقلاً لكل مندوب لفصل النقدية.</p>`,null);$('#repSale').onclick=()=>invoice('sale',{rep:id,warehouse:r.warehouse,branch:r.branch,payments:[{account:r.cash||'113',amount:0,rate:1000000,currency:S.settings.currency}]});$('#repReceipt').onclick=()=>{voucher('receipt');$('#modalBody [name=rep]').value=id;$('#modalBody [name=cash]').value=r.cash||'113'}}
function shiftDialog(){let open=S.shifts.find(x=>!x.closed);if(!open){modal('فتح وردية صندوق',`<div class="form-grid">${select('الصندوق','cash',S.accounts.filter(a=>a.parent==='110'),'111')}${field('النقد المعدود عند الفتح','actual','0','number','min="0" step="0.01"')}${field('اسم الموظف','employee','','text','required')}</div><p class="muted">فتح الوردية لا ينشئ نقداً؛ لإثبات تمويل الصندوق استخدم قيداً أو تحويلاً.</p>`,async f=>{await mutate(s=>{if(s.shifts.some(x=>!x.closed))throw Error('توجد وردية مفتوحة');let a=E.dec(f.get('actual')),b=E.balance(s,f.get('cash'));if(a!==b)throw Error('رصيد الفتح لا يطابق الأستاذ؛ سجّل تسوية أولاً');s.shifts.push({id:E.uid(),cash:f.get('cash'),employee:f.get('employee'),opening:a,start:s.docs.length,opened:new Date().toISOString()})})},'فتح الوردية')}else{let expected=E.balance(S,open.cash);modal('إقفال وردية — '+open.employee,`<div class="summary"><div><span>الافتتاحي</span><strong>${money(open.opening)}</strong></div><div><span>المتوقع الحالي</span><strong>${money(expected)}</strong></div></div><br>${field('النقد الفعلي','actual',num(expected),'number','step="0.01" min="0" required')}<p class="muted">يسجل الفرق للمراجعة ولا يُنشئ تسوية تلقائية.</p>`,async f=>{await mutate(s=>{let sh=s.shifts.find(x=>x.id===open.id);if(sh.closed)throw Error('الوردية مغلقة');sh.actual=E.dec(f.get('actual'));sh.expected=E.balance(s,sh.cash);sh.diff=sh.actual-sh.expected;sh.end=s.docs.length;sh.closed=new Date().toISOString();s.audit.push({id:E.uid(),time:sh.closed,action:'إقفال وردية',name:'الفرق '+money(sh.diff)})})},'إغلاق الوردية')}}
async function seedDemo(){if(S.docs.length||S.products.length)throw Error('تحميل البيانات التوضيحية متاح في قاعدة فارغة فقط');await mutate(s=>{E.put(s,'parties',{id:'customer1',name:'أسواق الندى — توضيحي',type:'customer',phone:'',creditLimit:0,terms:30});E.put(s,'parties',{id:'supplier1',name:'شركة التوريد — توضيحي',type:'supplier',phone:'',creditLimit:0,terms:30});E.put(s,'products',{id:'p1',code:'P001',name:'مياه معدنية 500 مل — توضيحي',category:'مشروبات',type:'stock',min:100000,tax:0,units:[{name:'حبة',factor:1000,price:200,barcode:'1001',decimal:false},{name:'باكيت',factor:24000,price:4000,barcode:'1002',decimal:false},{name:'كرتونة',factor:288000,price:42000,barcode:'1003',decimal:false}]});E.put(s,'products',{id:'p2',code:'P002',name:'أرز ممتاز — توضيحي',category:'مواد غذائية',type:'stock',min:10000,tax:0,units:[{name:'كيلو',factor:1000,price:900,barcode:'2001',decimal:true},{name:'كيس 25 كغ',factor:25000,price:20000,barcode:'2002',decimal:false}]});E.put(s,'reps',{id:'rep1',name:'مندوب المنطقة — توضيحي',warehouse:'van',branch:'main',phone:'',cash:'113',commissionBasis:'sales',commissionRate:200});const base={date:today(),branch:'main',warehouse:'main',currency:S.settings.currency,rate:1000000,costCenter:'general'};E.post(s,{...base,id:E.uid(),kind:'journal',note:'تمويل افتتاحي توضيحي',entries:[{account:'111',debit:1000000,credit:0},{account:'310',debit:0,credit:1000000}]});E.post(s,{...base,id:E.uid(),kind:'purchase',party:'supplier1',lines:[{product:'p1',unit:2,qty:10000,price:28800},{product:'p2',unit:1,qty:10000,price:15000}],payments:[]});E.post(s,{...base,id:E.uid(),kind:'sale',party:'customer1',lines:[{product:'p1',unit:1,qty:5000,price:4000},{product:'p2',unit:0,qty:15000,price:900}],payments:[{account:'111',amount:15000,rate:1000000,currency:S.settings.currency}]});E.post(s,{...base,id:E.uid(),kind:'transfer',toWarehouse:'van',lines:[{product:'p1',qty:288000}]});E.post(s,{...base,id:E.uid(),kind:'sale',warehouse:'van',rep:'rep1',party:'customer1',lines:[{product:'p1',unit:1,qty:3000,price:4000}],payments:[{account:'113',amount:12000,rate:1000000,currency:S.settings.currency}]})},'تم تحميل بيانات توضيحية موسومة بأسمائها')}
function scopeDialog(){modal('الخصائص وحدود هذه النسخة',`<div class="notice">نسخة محلية عملية ذات نطاق محدد، وليست ERP إنتاجياً مكتملاً لجميع بنود الطلب. راجع docs/STATUS.md داخل الحزمة قبل الاعتماد التشغيلي.</div><h3>منفّذ</h3><p>حفظ IndexedDB ذري، وحدات متعددة، شراء وبيع، دفع متعدد العملات، سندات مع تخصيص الفواتير، مرتجعات جزئية، متوسط تكلفة متحرك، تحويل وجرد وتالف، قيود وأستاذ وميزان وقائمة دخل وميزانية، مناديب واحتساب عمولة، رواتب أساسية، وصفات تصنيع، إهلاك ثابت، نسخ واستعادة، Excel وCSV وطباعة متصفح، PWA.</p><h3>غير منفّذ بالكامل</h3><p>خادم ومزامنة فعلية ومصادقة وصلاحيات آمنة، FIFO، التشغيلة والصلاحية والتسلسل، حجز المخزون، دورة شراء وتسليم متعددة المراحل، مصروفات شراء موزعة، شيكات وتسويات بنكية، أقساط وتنبيهات خلفية، موافقات وتسوية مناديب مقفلة، تسويات فروق صرف محققة، استيراد XLSX وتصدير صورة، طباعة Bluetooth Classic دون دعم من النظام، تسويات استحقاق ومقدمات تلقائية.</p><h3>التشغيل</h3><p>افتح index.html بعد فك الضغط. التثبيت PWA يحتاج HTTPS أو localhost. التخزين في file:// يختلف بين المتصفحات؛ احتفظ بنسخة JSON قبل نقل الملفات أو تغيير المتصفح. PDF متاح من نافذة الطباعة حسب النظام.</p>`,null)}
async function camera(){if(!window.BarcodeDetector||!navigator.mediaDevices?.getUserMedia){toast('المسح بالكاميرا غير مدعوم هنا. استخدم قارئ USB أو اكتب الباركود في البحث.');return}modal('مسح باركود','<video id="cameraVideo" autoplay playsinline style="width:100%;max-height:55vh"></video><p class="muted">وجّه الكاميرا نحو الباركود. أغلق النافذة لإنهاء المسح.</p>',null);try{let stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}});if(!$('#modal').open){stream.getTracks().forEach(t=>t.stop());return}window.cameraStream=stream;$('#cameraVideo').srcObject=stream;let detector=new BarcodeDetector(),last='',lastTime=0;let loop=async()=>{if(!window.cameraStream)return;try{let codes=await detector.detect($('#cameraVideo'));for(const c of codes){if(c.rawValue===last&&Date.now()-lastTime<1600)continue;last=c.rawValue;lastTime=Date.now();addBarcode(c.rawValue)}}catch{}if(window.cameraStream)setTimeout(loop,350)};loop()}catch(e){error(e);closeModal()}}
function addBarcode(code){for(const p of S.products.filter(p=>!p.archived)){let unit=p.units.findIndex(u=>u.barcode===code);if(unit>=0){addCart(p.id,unit);toast('أُضيف '+p.name);return true}}toast('الباركود غير مسجل');return false}
function addCart(id,unit=0){let p=find('products',id),l=cart.find(x=>x.product===id&&x.unit===unit);if(l)l.qty+=1000;else cart.push({product:id,unit,qty:1000,price:p.units[unit].price,discount:0});persistCart();render()}
const actions={xlsx:()=>{let blob=XLSXExport.workbook(exportHeaders,exportData);let a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download='Rawan-'+route+'-'+today()+'.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(url),3000)},filter:filters,export:csvExport,printReport,backup:()=>download(JSON.stringify({format:'rawan-backup',version:1,created:new Date().toISOString(),data:S},null,2),'Rawan-backup-'+today()+'.json'),restore:()=>chooseFile('.json',async f=>{let data=JSON.parse(await readFile(f));if(data.format!=='rawan-backup'||data.version!==1)throw Error('ملف نسخ غير معتمد');E.validate(data.data);if(!confirm('استبدال البيانات الحالية بالنسخة المختارة؟ احفظ نسخة من الحالية أولاً.'))return;let r=await Store.restore(data.data);S=r.state;cart=[];persistCart();render();toast('تمت الاستعادة والتحقق')}),validate:()=>{E.validate(S);toast('متوازن: القيود والمخزون والأستاذ متطابقة')},demo:seedDemo,audit:showAudit,scope:scopeDialog,journals:showJournals,stockHistory:showStockHistory,openingCash:journal,shift:shiftDialog,camera,drafts:showDrafts,quote:()=>{invoice('sale');$('#modalTitle').textContent='عرض سعر / طلب بيع';$('#submitModal').style.display='none';$('#saveDraft').textContent='حفظ عرض سعر / طلب دون أثر مالي';const old=$('#saveDraft').onclick;if(draft.editOriginal){$('#modalTitle').textContent='تعديل فاتورة #'+draft.editNumber;$('#saveDraft').style.display='none'}$('#saveDraft').onclick=async()=>{await old();if(!$('#modal').open)await mutate(s=>{let d=s.drafts.find(x=>x.id===pendingId);if(d)d.draftType='عرض سعر / طلب بيع'})}},checkout:()=>{if(!cart.length)throw Error('أضف أصنافاً للسلة');invoice('sale',{},true)},suspend:async()=>{if(!cart.length)return;await mutate(s=>s.drafts.push({id:E.uid(),kind:'sale',warehouse:session.getItem('posWarehouse')||'main',lines:E.clone(cart),saved:today()}),'تم تعليق الفاتورة');cart=[];persistCart();render()},clearCart:()=>{if(cart.length&&confirm('تفريغ السلة؟')){cart=[];persistCart();render()}},company:()=>modal('بيانات المؤسسة',`<div class="form-grid">${field('اسم المؤسسة','company',S.settings.company,'text','required')}${field('الهاتف','phone',S.settings.phone)}${field('العنوان','address',S.settings.address)}${select('العملة الأساسية','currency',S.currencies,S.settings.currency)}${field('بداية السنة المالية','yearStart',S.settings.yearStart,'date','required')}${select('مقاس الطباعة','print',[{id:'58mm',name:'حراري 58 مم'},{id:'80mm',name:'حراري 80 مم'},{id:'A4',name:'A4'}],S.settings.print)}</div>`,async f=>{await mutate(s=>{if(s.docs.length&&(f.get('currency')!==s.settings.currency||f.get('yearStart')!==s.settings.yearStart))throw Error('لا يمكن تغيير العملة الأساسية أو بداية السنة بعد الترحيل');Object.assign(s.settings,Object.fromEntries(f))})}),closePeriod:()=>modal('إقفال الإيرادات والمصروفات',field('تاريخ الإقفال','date',today(),'date','required')+'<div class="notice">يحوّل صافي النتيجة إلى الأرباح المحتجزة ويمنع أي ترحيل بتاريخ يساوي تاريخ الإقفال أو يسبقه. لا يمكن إعادة فتح الفترة من الواجهة.</div>',async f=>{await mutate(s=>E.post(s,{id:E.uid(),kind:'close',date:f.get('date')}))},'إقفال الفترة'),reset:()=>modal('قاعدة بيانات فارغة','<div class="notice">سيتم حذف جميع البيانات من هذا المتصفح. نزّل نسخة احتياطية أولاً. لا يمكن التراجع دون النسخة.</div>'+field('اكتب حذف للتأكيد','confirm','','text','required'),async f=>{if(f.get('confirm')!=='حذف')throw Error('كلمة التأكيد غير صحيحة');let r=await Store.restore(E.fresh());S=r.state;cart=[];persistCart();render()},'حذف البيانات'),import:()=>modal('استيراد أصناف CSV','<p>أعمدة الملف بالترتيب: <code>code,name,unit,price,barcode</code> مع سطر عناوين. كل سطر ينشئ صنفاً بوحدة أساسية واحدة. حفظ كل الملف كوحدة واحدة.</p>'+field('الملف UTF-8','file','','file','accept=".csv" required'),async f=>{let str=(await readFile(f.get('file'))).replace(/^\uFEFF/,'');let rows=parseCSV(str).slice(1).filter(r=>r.some(Boolean));await mutate(s=>{for(const r of rows){if(r.length!==5)throw Error('عدد أعمدة غير صحيح');E.put(s,'products',{id:E.uid(),code:r[0],name:r[1],type:'stock',min:0,tax:0,units:[{name:r[2],factor:1000,price:E.dec(r[3]),barcode:r[4],decimal:false}]})}},'تم استيراد '+rows.length+' صنفاً')})};
function parseCSV(text){let rows=[],row=[],field='',quoted=false;for(let i=0;i<text.length;i++){let c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){field+='"';i++}else quoted=!quoted}else if(c===','&&!quoted){row.push(field);field=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(field);rows.push(row);row=[];field=''}else field+=c}if(quoted)throw Error('علامة اقتباس غير مغلقة');if(field||row.length){row.push(field);rows.push(row)}return rows}
document.addEventListener('click',async ev=>{let b=ev.target.closest('button');if(!b)return;try{let d=b.dataset;if(Object.keys(d).length)ev.preventDefault();if(d.action&&actions[d.action])await actions[d.action]();else if(d.new)newDoc(d.new);else if(d.add)editEntity(d.add);else if(d.edit){let [t,id]=d.edit.split(':');editEntity(t,id)}else if(d.view)viewDoc(d.view);else if(d.cart)addCart(d.cart);else if(d.cartDelete!==undefined){cart.splice(+d.cartDelete,1);persistCart();render()}else if(d.page){page=+d.page;render()}else if(d.report){report=d.report;page=1;render()}else if(d.statement)showLedger(null,d.statement);else if(d.ledger)showLedger(d.ledger);else if(d.printdoc)printHTML(receiptHTML(S.docs.find(x=>x.id===d.printdoc)));else if(d.sharedoc){let doc=S.docs.find(x=>x.id===d.sharedoc);let text=`${S.settings.company}\n${E.labels[doc.kind]} ${doc.number}\n${doc.date}\nالإجمالي: ${money(doc.total??doc.amount??doc.totalBase??0)} ${doc.currency}\n${doc.lines.map(l=>`${l.name} × ${qty(l.qty||0)} ${l.unitName||''}`).join('\n')}`;if(navigator.share)await navigator.share({title:E.labels[doc.kind],text});else if(navigator.clipboard){await navigator.clipboard.writeText(text);toast('تم نسخ نص المستند')}else modal('نص للمشاركة',`<textarea rows="12">${esc(text)}</textarea>`,null)}else if(d.return)returnDoc(d.return);else if(d.reverse){let original=d.reverse;if(confirm('عكس الأثر المحاسبي والمخزني لهذا المستند؟')){await mutate(s=>E.post(s,{id:E.uid(),kind:'reverse',original,date:today()}),'تم إنشاء مستند عكسي');closeModal()}}else if(d.draft){let draft=find('drafts',d.draft);invoice(draft.kind||'sale',draft)}else if(d.draftDelete){if(confirm('حذف المسودة؟')){await mutate(s=>s.drafts=s.drafts.filter(x=>x.id!==d.draftDelete));showDrafts()}}else if(d.rep)showRep(d.rep)}catch(err){error(err)}});
document.addEventListener('input',ev=>{if(ev.target.id==='search'){let pos=ev.target.selectionStart;query=ev.target.value;page=1;render();$('#search')?.focus();$('#search')?.setSelectionRange(pos,pos)}});
document.addEventListener('change',ev=>{let x=ev.target;try{if(x.dataset.cartUnit!==undefined){let l=cart[+x.dataset.cartUnit];l.unit=+x.value;l.price=E.priceFor(S,l.product,l.unit,typeof posParty==='undefined'?'':posParty);persistCart();render()}if(x.dataset.cartQty!==undefined){cart[+x.dataset.cartQty].qty=E.dec(x.value,3);persistCart();render()}if(x.dataset.cartPrice!==undefined){cart[+x.dataset.cartPrice].price=E.dec(x.value);persistCart();render()}if(x.id==='posWarehouse')session.setItem('posWarehouse',x.value)}catch(err){error(err);render()}});
document.addEventListener('keydown',ev=>{if(ev.key==='F2'){ev.preventDefault();$('#search')?.focus()}if(ev.key==='F8'&&route==='pos'&&!$('#modal').open){ev.preventDefault();try{actions.checkout()}catch(e){error(e)}}if(ev.key==='Enter'&&ev.target.id==='search'&&route==='pos'){ev.preventDefault();if(addBarcode(ev.target.value)){query='';render();$('#search')?.focus()}}});
