(async()=>{try{try{if(localStorage.getItem('rawan-theme')==='dark')document.body.classList.add('dark')}catch{}if(window.WatheeqAuth)await WatheeqAuth.ready;await Store.open();if(window.WatheeqSync)await WatheeqSync.start();S=await Store.read();E.validate(S);route=location.hash.slice(1)||'dashboard';try{cart=JSON.parse(session.getItem('rawan-cart')||'[]').filter(l=>find('products',l.product))}catch{cart=[]}render();if('serviceWorker'in navigator&&['https:','http:'].includes(location.protocol))navigator.serviceWorker.register('./sw.js').catch(()=>toast('تعذر تجهيز التخزين دون اتصال؛ التشغيل الحالي متاح'));}catch(e){$('#content').innerHTML=heading('تعذر فتح قاعدة البيانات','لم يتم تشغيل وضع مؤقت حتى لا تفقد عملياتك.')+`<div class="notice">${esc(e.message)}<br>جرّب متصفح Chrome أو Edge، أو شغّل start-local.py وافتح localhost. إذا كانت لديك بيانات سابقة فلا تمسح بيانات المتصفح قبل حفظ نسخة.</div>`;$('#storageState').textContent='التخزين غير متاح';$('#quickBtn').disabled=true}})();
